const express = require('express');
const fs = require('fs');
const path = require('path');
const crypto = require('crypto');
const { pipeline, Transform } = require('stream');
const { db } = require('../models/tax');

const app = express();

class DecryptDocumentStream extends Transform {
  constructor(secretKey, iv) {
    super();
    this.decipher = crypto.createDecipheriv('aes-256-cbc', secretKey, iv);
  }

  _transform(chunk, encoding, callback) {
    try {
      const decrypted = this.decipher.update(chunk);
      callback(null, decrypted);
    } catch (err) {
      callback(err);
    }
  }

  _flush(callback) {
    try {
      const finalChunk = this.decipher.final();
      callback(null, finalChunk);
    } catch (err) {
      callback(err);
    }
  }
}

app.get('/api/v1/tax-documents/:documentId/stream', async (req, res) => {
  if (!req.user || !req.user.id) {
    return res.status(401).json({ error: 'Authentication required' });
  }

  // Validate object ownership before initiating file stream pipeline
  const documentRecord = await db.taxDocuments.findOne({
    where: {
      documentId: req.params.documentId,
      ownerUserId: req.user.id
    }
  });

  if (!documentRecord) {
    return res.status(403).json({ error: 'Access denied or document not found' });
  }

  const filePath = path.join('/var/storage/tax_vault', `${req.params.documentId}.enc`);
  if (!fs.existsSync(filePath)) {
    return res.status(404).json({ error: 'Document file missing' });
  }

  res.setHeader('Content-Type', 'application/pdf');
  res.setHeader('Content-Disposition', `inline; filename="tax_form_${req.params.documentId}.pdf"`);

  const fileStream = fs.createReadStream(filePath);
  const decryptStream = new DecryptDocumentStream(
    Buffer.from(process.env.TAX_VAULT_KEY, 'hex'),
    Buffer.from(process.env.TAX_VAULT_IV, 'hex')
  );

  pipeline(fileStream, decryptStream, res, (err) => {
    if (err && !res.headersSent) {
      res.status(500).json({ error: 'Stream pipeline error' });
    }
  });
});

app.listen(8080);
